PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS themes(id TEXT PRIMARY KEY, name TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS node_theme_memberships(node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, theme_id TEXT NOT NULL REFERENCES themes(id), PRIMARY KEY(node_id,theme_id));
CREATE TABLE IF NOT EXISTS edges(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES nodes(id), target_id TEXT NOT NULL REFERENCES nodes(id), type TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('verified','interpretation','hypothesis')), data TEXT NOT NULL, CHECK(source_id <> target_id));
CREATE INDEX IF NOT EXISTS edge_source ON edges(source_id);
CREATE INDEX IF NOT EXISTS edge_target ON edges(target_id);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, url TEXT NOT NULL UNIQUE, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS edge_evidence(edge_id TEXT REFERENCES edges(id) ON DELETE CASCADE, source_id TEXT REFERENCES sources(id), PRIMARY KEY(edge_id,source_id));
CREATE TABLE IF NOT EXISTS node_sources(node_id TEXT REFERENCES nodes(id) ON DELETE CASCADE, source_id TEXT REFERENCES sources(id), PRIMARY KEY(node_id,source_id));
CREATE TABLE IF NOT EXISTS social_posts(id TEXT PRIMARY KEY REFERENCES sources(id), platform TEXT NOT NULL, external_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS signals(id TEXT PRIMARY KEY, node_id TEXT REFERENCES nodes(id), source_id TEXT REFERENCES sources(id), title TEXT NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL, published_at TEXT);
CREATE INDEX IF NOT EXISTS signal_time ON signals(created_at);
CREATE TABLE IF NOT EXISTS node_events(id TEXT PRIMARY KEY,node_id TEXT NOT NULL REFERENCES nodes(id),title TEXT NOT NULL,event_date TEXT NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS ingestion_jobs(id TEXT PRIMARY KEY,adapter TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,started_at TEXT NOT NULL,finished_at TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS editorial_reviews(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at TEXT NOT NULL,reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS saved_views(id TEXT PRIMARY KEY,label TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watchlists(id TEXT PRIMARY KEY,label TEXT NOT NULL,node_ids TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
